 1	import * as fs from 'node:fs';
 2	import * as path from 'node:path';
 3	import type { AppConfig } from '../config/config.types.js';
 4	import type { ProjectManager } from '../models/project/project.manager.js';
 5	import type { WorkspaceManager } from '../models/workspace/workspace.manager.js';
 6	import type { RepositoryManager } from '../models/repository/repository.manager.js';
 7	import { cloneRepository } from '../git/git-clone.js';
 8	import { resolveCredential, injectCredentialToken, extractHost, stripEmbeddedCredentials } from '../git/git-credentials.js';
 9	import {
10	    generateWorkspaceFile,
11	    removeWorkspaceFile,
12	    getWorkspaceFilePath,
13	} from './vscode-workspace.js';
14	import { STABLE_WORKSPACE_ID } from '../models/workspace/workspace.types.js';
15	import { isValidWorkspaceId } from '../utils/slug.js';
16	import { CLONE_TIMEOUT_MS } from './orchestration.types.js';
17	import type { OrchestrationResult, OrchestrationRepoResult } from './orchestration.types.js';
18	import type { ErrorLogManager } from '../error-log/error-log.manager.js';
19	
20	/**
21	 * High-level orchestrator for workspace lifecycle operations.
22	 * Composes the stateless git and file-system layers with data-model reads/writes.
23	 *
24	 * Responsibility split:
25	 * - WorkspaceManager: business-rule validation and data persistence.
26	 * - WorkspaceOrchestrator: git cloning, folder management, and VS Code file generation.
27	 *
28	 * ## Workspace creation flow
29	 *
30	 * The caller is expected to create the workspace data entry (via
31	 * `WorkspaceManager.create()`) before calling `createWorkspace()`.
32	 * `createWorkspace()` handles only the filesystem side: creating the folder,
33	 * cloning repositories, and generating the VS Code .code-workspace file.
34	 *
35	 * ## STABLE workspace invariant
36	 *
37	 * `deleteWorkspace()` and `renameWorkspace()` both reject the STABLE
38	 * workspace ID. This mirrors the protection enforced at the data layer by
39	 * `WorkspaceManager`.
40	 */
41	export class WorkspaceOrchestrator {
42	    constructor(
43	        private readonly config: AppConfig,
44	        private readonly projectManager: ProjectManager,
45	        private readonly workspaceManager: WorkspaceManager,
46	        private readonly repositoryManager: RepositoryManager,
47	        private readonly errorLogManager?: ErrorLogManager,
48	    ) {}
49	
50	    // -------------------------------------------------------------------------
51	    // Private helpers
52	    // -------------------------------------------------------------------------
53	
54	    private workspaceFolder(projectId: string, workspaceId: string): string {
55	        return path.join(this.config.projectsFolder, projectId, workspaceId);
56	    }
57	
58	    private repoPath(projectId: string, workspaceId: string, repoId: string): string {
59	        return path.join(this.config.projectsFolder, projectId, workspaceId, repoId);
60	    }
61	
62	    private wsFilePath(projectId: string, workspaceId: string): string {
63	        return getWorkspaceFilePath(this.config.projectsFolder, projectId, workspaceId);
64	    }
65	
66	    // -------------------------------------------------------------------------
67	    // Public API
68	    // -------------------------------------------------------------------------
69	
70	    /**
71	     * Creates the workspace folder on disk, clones all project repositories into
72	     * it, and generates a VS Code .code-workspace file.
73	     *
74	     * Clone failures are captured per-repository in the returned result and do
75	     * not abort the operation: the workspace folder and .code-workspace file are
76	     * always created even when some clones fail.
77	     *
78	     * The workspace data entry is expected to already exist (created by the
79	     * caller via `WorkspaceManager.create()` before invoking this method).
80	     *
81	     * @throws {Error} If the project does not exist.
82	     * @remarks If `errorLogManager` is injected and `errorLogManager.append()`
83	     *   itself throws (e.g. disk full when writing `error-log.json`), that
84	     *   exception propagates out of the `Promise.all` callback and converts a
85	     *   per-repository clone failure into a full rejection of this method.
86	     *   Logging exceptions are **not** swallowed.
87	     */
88	    async createWorkspace(projectId: string, workspaceId: string): Promise<OrchestrationResult> {
89	        const project = this.projectManager.getById(projectId);
90	        if (!project) {
91	            throw new Error(
92	                `Cannot create workspace: project with ID "${projectId}" does not exist.`
93	            );
94	        }
95	
96	        const wsFolder = this.workspaceFolder(projectId, workspaceId);
97	        fs.mkdirSync(wsFolder, { recursive: true });
98	
99	        const resolvedProjectsFolder = path.resolve(this.config.projectsFolder);

101	 * @returns The matching `GitCredentialEntry`, or `null` when resolution fails.
102	 *
103	 * @remarks
104	 * **SECURITY — host/credential coherence (explicit `credentialId` path):**
105	 * When `credentialId` is supplied, resolution performs only an exact `id` match;
106	 * no cross-validation against the URL's hostname is performed. A caller could
107	 * inadvertently (or maliciously) pass a `credentialId` belonging to a different
108	 * host and receive a credential for that host. The caller is responsible for
109	 * ensuring the URL's host is consistent with the credential's configured `host`
110	 * before using the resolved token. This validation should occur at the call site
111	 * (e.g. in the orchestrators) before passing the authenticated URL to git.
112	 */
113	export function resolveCredential(
114	    url: string,
115	    credentials: GitCredentialEntry[],
116	    credentialId?: string,
117	): GitCredentialEntry | null {
118	    if (credentialId !== undefined) {
119	        return credentials.find((c) => c.id === credentialId) ?? null;
120	    }
121	
122	    const host = extractHost(url);
123	    if (host === null) return null;
124	
125	    const matches = credentials.filter((c) => c.host === host);
126	    return matches.length === 1 ? matches[0] : null;
127	}
128	
129	/**
130	 * Injects a single token into an HTTPS URL as the userinfo component.
131	 *
132	 * This is the simplified successor to `injectCredentials()`. It accepts a
133	 * pre-resolved token string directly (obtained from a {@link GitCredentialEntry}
134	 * via {@link resolveCredential}) instead of the full credentials map.
135	 *
136	 * The token is written as the WHATWG URL username only (no password component)
137	 * since Personal Access Tokens are typically passed in the username field.
138	 * Special characters in the token are automatically percent-encoded by the
139	 * URL serialiser — no string concatenation is used.
140	 *
141	 * @param url   - The remote URL to modify.
142	 * @param token - The credential token to inject.
143	 * @returns The URL with the token injected, or the original URL unchanged for
144	 *   non-HTTPS or malformed URLs.
145	 */
146	export function injectCredentialToken(url: string, token: string): string {
147	    const host = extractHost(url);
148	    if (host === null) return url;
149	
150	    try {
151	        const parsed = new URL(url);
152	        parsed.username = token;
153	        parsed.password = '';
154	        return parsed.toString();
155	    } catch {
156	        return url;
157	    }
158	}
159	
160	/**
161	 * Returns `true` when the URL contains an embedded username (and optional password)
162	 * in the userinfo section (e.g. `https://token@github.com/...`).
163	 *
164	 * Always returns `false` for non-HTTPS or malformed URLs.
165	 *
166	 * @param url - The URL to inspect.
167	 */
168	export function hasEmbeddedCredentials(url: string): boolean {
169	    if (!url) return false;
170	    try {
171	        const parsed = new URL(url);
172	        if (parsed.protocol !== 'https:') return false;
173	        return parsed.username !== '';
174	    } catch {
175	        return false;
176	    }
177	}
178	
179	/**
180	 * Redacts embedded HTTPS credentials from a URL or arbitrary string (e.g. a
181	 * git error message such as `"fatal: repository 'https://token@host/...' not found"`).
182	 *
183	 * Pure HTTPS URLs are sanitised via the WHATWG URL object (clean user/password
184	 * removal). All other inputs — non-HTTPS URLs, prose strings, and unparseable
185	 * values — fall through to a regex scrub that replaces any `https?://…@` pattern
186	 * with `https://***@`, preserving the host and path while redacting the token.
187	 *
188	 * @param input - The URL or string to sanitise.
189	 * @returns The sanitised string, or the original if no embedded credentials are
190	 *   found.
191	 */
192	export function stripEmbeddedCredentials(input: string): string {
193	    if (!input) return input;
194	    try {
195	        const parsed = new URL(input);
196	        if (parsed.protocol === 'https:') {
197	            parsed.username = '';
198	            parsed.password = '';
199	            return parsed.toString();
200	        }

100	
101	        const repoResults: OrchestrationRepoResult[] = await Promise.all(
102	            project.Repositories.map(async (repoId): Promise<OrchestrationRepoResult> => {
103	                const repo = this.repositoryManager.getById(repoId);
104	                if (!repo) {
105	                    return {
